/**
 * M6 lane 2 fixtures: write-side fidelity core (F2-F8, F15).
 *
 * F1 (`identity-minimal.xlsx`) is generated by generate-fixtures.mjs and is
 * consumed, not rewritten, here. Every fixture below is hand-authored OOXML
 * with fixed zip timestamps and stable ordering, so `npm run fixtures` is
 * byte-identical on every run (scripts/fixtures/groups/README.md).
 *
 * The fixtures name the clause of file-compat §9 they prove; the assertions
 * live in tests/m6-roundtrip.test.ts.
 */

const DAY_MS = 86_400_000;

/** 1900 date system serial. Excel's fake 29 February 1900 is built in. */
function serial1900(year, month, day, fraction = 0) {
  return Math.floor((Date.UTC(year, month - 1, day) - Date.UTC(1899, 11, 30)) / DAY_MS) + fraction;
}

/** 1904 date system serial (the epoch is 1 January 1904). */
function serial1904(year, month, day, fraction = 0) {
  return Math.floor((Date.UTC(year, month - 1, day) - Date.UTC(1904, 0, 1)) / DAY_MS) + fraction;
}

const CONTENT_TYPE = {
  comments: 'application/vnd.openxmlformats-officedocument.spreadsheetml.comments+xml',
  threadedComments: 'application/vnd.ms-excel.threadedcomments+xml',
  persons: 'application/vnd.ms-excel.person+xml',
  calcChain: 'application/vnd.openxmlformats-officedocument.spreadsheetml.calcChain+xml',
  externalLink: 'application/vnd.openxmlformats-officedocument.spreadsheetml.externalLink+xml',
};

/**
 * packageEntries leaves an unknown part at `application/xml`. Comments,
 * threaded comments, persons, calcChain and external links each need their
 * registered content type, so patch `[Content_Types].xml` before zipping. An
 * existing override for the same part is replaced, never duplicated: OPC allows
 * one override per part. The rezip keeps the generator's fixed timestamp and
 * level, so the output is deterministic.
 */
function withContentTypes(bytes, overrides) {
  if (overrides.length === 0) return bytes;
  const entries = unzipSync(bytes);
  let contentTypes = new TextDecoder().decode(entries['[Content_Types].xml']);
  for (const [part, type] of overrides) {
    const replacement = `<Override PartName="/${part}" ContentType="${type}"/>`;
    const pattern = new RegExp(`<Override PartName="/${escapeRegExp(part)}"[^>]*/>`);
    contentTypes = pattern.test(contentTypes)
      ? contentTypes.replace(pattern, replacement)
      : contentTypes.replace('</Types>', `  ${replacement}\n</Types>`);
  }
  entries['[Content_Types].xml'] = new TextEncoder().encode(contentTypes);
  return zipSync(entries, { level: 6, mtime: new Date('1980-01-01T00:00:00Z') });
}

function escapeRegExp(text) {
  return text.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

function buildPackage({ workbook, workbookRels, sheets, sharedStrings, extra = {}, overrides = [] }) {
  return withContentTypes(
    packageEntries({ workbook, workbookRels, sheets, sharedStrings, extra }),
    overrides,
  );
}

/** A minimal single-sheet workbook wrapper used by the focused fixtures. */
function simpleWorkbook({ date1904 = false, sheetName = 'Sheet1', calcPr = '' } = {}) {
  return `${XML_HEADER}
<workbook xmlns="${SPREADSHEET_NS}" xmlns:r="${REL_NS}">
  <workbookPr date1904="${date1904 ? '1' : '0'}"/>
  <bookViews><workbookView activeTab="0"/></bookViews>
  <sheets><sheet name="${sheetName}" sheetId="1" r:id="rId1"/></sheets>
  ${calcPr}
</workbook>`;
}

function simpleWorkbookRels(parts) {
  return `${XML_HEADER}
<Relationships xmlns="${PACKAGE_REL_NS}">
${parts
  .map(
    ([id, type, target]) =>
      `  <Relationship Id="${id}" Type="${REL_NS}/${type}" Target="${target}"/>`,
  )
  .join('\n')}
</Relationships>`;
}

