/** The minimal style sheet several fixtures share. */
function f4StylesXml() {
  return `${XML_HEADER}
<styleSheet xmlns="${SPREADSHEET_NS}">
  <fonts count="1"><font><sz val="11"/><name val="Calibri"/><family val="2"/></font></fonts>
  <fills count="2"><fill><patternFill patternType="none"/></fill><fill><patternFill patternType="gray125"/></fill></fills>
  <borders count="1"><border><left/><right/><top/><bottom/><diagonal/></border></borders>
  <cellStyleXfs count="1"><xf numFmtId="0" fontId="0" fillId="0" borderId="0"/></cellStyleXfs>
  <cellXfs count="1"><xf numFmtId="0" fontId="0" fillId="0" borderId="0" xfId="0"/></cellXfs>
  <cellStyles count="1"><cellStyle name="Normal" xfId="0" builtinId="0"/></cellStyles>
</styleSheet>`;
}

export function build({ compatDir }) {
  const fixtures = [
    ['identity-full.xlsx', f2Package()],
    ['styles-append.xlsx', f3Package()],
    ['shared-strings-append.xlsx', f4Package()],
    ['formula-cached.xlsx', f5Package()],
    ['formula-uncached.xlsx', f6Package()],
    ['unsupported-function.xlsx', f7Package()],
    ['array-shared.xlsx', f8Package()],
    ['date1904.xlsx', f15Package()],
  ];
  for (const [name, bytes] of fixtures) {
    const path = join(compatDir, name);
    writeFileSync(path, bytes);
    console.log(`Wrote ${path}`);
  }
}
